const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const { Buffer } = require('buffer');

// Configuration for upload processing
const UPLOAD_DIR = '/var/uploads/verified';
const MAX_FILE_SIZE = 10 * 1024 * 1024;
const HMAC_SECRET = crypto.randomBytes(32);

class IntegrityVerifier {
  constructor(algorithm = 'sha256') {
    this.algorithm = algorithm;
    this.trustedSignatures = new Map();
  }

  registerTrustedUploader(uploaderId, sharedSecret) {
    const keyMaterial = crypto.pbkdf2Sync(
      sharedSecret, 'uploader-salt-v2', 100000, 32, 'sha256'
    );
    this.trustedSignatures.set(uploaderId, keyMaterial);
  }

  computeHmac(uploaderId, data) {
    const key = this.trustedSignatures.get(uploaderId);
    if (!key) throw new Error('Unknown uploader');
    const hmac = crypto.createHmac(this.algorithm, key);
    hmac.update(data);
    return hmac.digest();
  }

  verifyIntegrity(uploaderId, data, providedSignature) {
    const expected = this.computeHmac(uploaderId, data);
    return this._safeCompare(expected, providedSignature);
  }

  _safeCompare(a, b) {
    if (!Buffer.isBuffer(a)) a = Buffer.from(a);
    if (!Buffer.isBuffer(b)) b = Buffer.from(b);
    if (a.length !== b.length) return false;
    return crypto.timingSafeEqual(a, b);
  }
}

class EncodingNormalizer {
  constructor() {
    this.supportedEncodings = ['utf8', 'ascii', 'latin1', 'base64', 'hex'];
  }

  normalizePayload(rawBuffer, declaredEncoding) {
    const encoding = this._resolveEncoding(declaredEncoding);
    // Convert to string using declared encoding, then back to buffer as utf8
    const asString = rawBuffer.toString(encoding);
    return Buffer.from(asString, 'utf8');
  }

  _resolveEncoding(enc) {
    const normalized = enc.toLowerCase().replace(/[^a-z0-9]/g, '');
    if (this.supportedEncodings.includes(normalized)) {
      return normalized;
    }
    return 'utf8';
  }
}

class UploadProcessor {
  constructor() {
    this.verifier = new IntegrityVerifier();
    this.normalizer = new EncodingNormalizer();
    this.processedFiles = new Map();
  }

  async processUpload(uploaderId, fileBuffer, metadata) {
    // Step 1: Validate metadata structure
    this._validateMetadata(metadata);

    // Step 2: Size check on raw upload
    if (fileBuffer.length > MAX_FILE_SIZE) {
      throw new Error('File exceeds maximum size');
    }

    // Step 3: Normalize encoding before integrity check
    const normalizedData = this.normalizer.normalizePayload(
      fileBuffer, metadata.encoding || 'utf8'
    );

    // Step 4: Verify HMAC signature against normalized data
    const signatureBuffer = Buffer.from(metadata.signature, 'hex');
    const isValid = this.verifier.verifyIntegrity(
      uploaderId, normalizedData, signatureBuffer
    );

    if (!isValid) {
      throw new Error('Integrity verification failed');
    }

    // Step 5: Write verified file
    const fileId = crypto.randomUUID();
    const safeName = fileId + this._safeExtension(metadata.filename);
    const destPath = path.join(UPLOAD_DIR, safeName);

    // Step 6: Write the normalized (verified) data
    await fs.promises.writeFile(destPath, normalizedData);

    this.processedFiles.set(fileId, {
      uploaderId,
      path: destPath,
      verifiedAt: Date.now(),
      hash: crypto.createHash('sha256').update(normalizedData).digest('hex')
    });

    return { fileId, path: destPath, verified: true };
  }

  _validateMetadata(metadata) {
    if (!metadata || typeof metadata !== 'object') {
      throw new Error('Invalid metadata');
    }
    if (!metadata.signature || typeof metadata.signature !== 'string') {
      throw new Error('Missing signature');
    }
    if (!/^[0-9a-f]+$/i.test(metadata.signature)) {
      throw new Error('Invalid signature format');
    }
    if (metadata.filename && typeof metadata.filename !== 'string') {
      throw new Error('Invalid filename');
    }
  }

  _safeExtension(filename) {
    if (!filename) return '.bin';
    const ext = path.extname(filename).toLowerCase();
    const allowed = ['.txt', '.json', '.xml', '.csv', '.bin', '.dat'];
    return allowed.includes(ext) ? ext : '.bin';
  }
}

// Export for use in Express/Koa route handlers
module.exports = { UploadProcessor, IntegrityVerifier, EncodingNormalizer };
